import ast

# Parse the code
user_code = code
tree = ast.parse(user_code)

# Check if Person class is defined
class_nodes = [node for node in ast.walk(tree) if isinstance(node, ast.ClassDef)]
class_names = [cls.name for cls in class_nodes]

if 'Person' not in class_names:
    raise AssertionError('Step 1: Person class not defined')

# Find Person class and check its methods
for node in class_nodes:
    if node.name == 'Person':
        method_names = [item.name for item in node.body if isinstance(item, ast.FunctionDef)]

        if '__init__' not in method_names:
            raise AssertionError('Step 1: Person class missing __init__ method')
        if 'greet' not in method_names:
            raise AssertionError('Step 2: Person class missing greet method')

        # Check greet method has self parameter
        for item in node.body:
            if isinstance(item, ast.FunctionDef) and item.name == 'greet':
                args = item.args.args
                if len(args) < 1 or args[0].arg != 'self':
                    raise AssertionError('greet method should have self as first parameter')
        break

print('TEST_PASSED')
